import type { ColumnDescription } from '../sql-engine/warehouse-driver.js';

/**
 * Ports of upstream's default database templates (`upstream_core/templates/defaults/databases/*.md.j2`) and the
 * sync file markers (`commands/sync/markers.py`). Only `columns` and `preview` (upstream's defaults) are
 * rendered; `profiling`, `ai_summary` and `query_history` are not ported yet.
 */

const GENERATED_MARKER =
	'---\ntype: generated\ncomment: This file is managed and generated by the agent, do not modify it!\n---';
const MANUAL_MARKER =
	'---\ntype: manual\ncomment: These are manual notes you want the agent to keep in mind, safe to edit.\n---';

export function withGeneratedMarker(content: string): string {
	return `${GENERATED_MARKER}\n\n${content}`;
}

export const ANNOTATIONS_FILE_CONTENT = `${MANUAL_MARKER}\n`;

export function renderColumnsTemplate(input: {
	tableName: string;
	dataset: string;
	description: string | null;
	rowCount: number;
	columns: ColumnDescription[];
}): string {
	const lines = [
		`# ${input.tableName}`,
		'',
		`**Dataset:** \`${input.dataset}\``,
		'',
		'## Description',
		'',
		input.description ?? '_No description available._',
		'',
		'## Table Metadata',
		'',
		'| Property | Value |',
		'|----------|-------|',
		`| **Row Count** | ${input.rowCount.toLocaleString('en-US')} |`,
		'',
		`## Columns (${input.columns.length})`,
		'',
		...input.columns.map(
			(column) =>
				`- ${column.name} (${column.type}${column.description ? `, "${truncateMiddle(column.description, 256)}"` : ''})`,
		),
		'',
	];
	return `${lines.join('\n')}\n`;
}

export function renderPreviewTemplate(input: {
	tableName: string;
	dataset: string;
	rows: Record<string, unknown>[];
}): string {
	const lines = [
		`# ${input.tableName} - Preview`,
		'',
		`**Dataset:** \`${input.dataset}\``,
		'',
		`## Rows (${input.rows.length})`,
		'',
		...input.rows.map((row) => `- ${pythonJson(row)}`),
		'',
	];
	return `${lines.join('\n')}\n`;
}

/** Placeholder written when a template fails and no previous file exists (`_placeholder_for_failed_render`). */
export function failedRenderPlaceholder(tableName: string, templateName: string, error: unknown): string {
	const message = error instanceof Error ? error.message : String(error);
	const reason = message.split('\n')[0] || (error instanceof Error ? error.name : 'Error');
	return `# ${tableName}\n\n${templateName} not generated: ${reason}\n`;
}

/** `truncate_middle_with_length`: keep head and tail, note the original length in the middle. */
export function truncateMiddle(text: string, maxLength: number): string {
	if (maxLength <= 0 || text.length <= maxLength) {
		return text;
	}
	const marker = `…[truncated, ${text.length} chars]…`;
	const keep = Math.max(maxLength - marker.length, 0);
	const head = Math.ceil(keep / 2);
	const tail = Math.floor(keep / 2);
	return text.slice(0, head) + marker + (tail ? text.slice(-tail) : '');
}

/** `DatabaseContext._cap_preview_value`: long strings and JSON values are truncated in the middle. */
export function capPreviewValue(value: unknown, maxLength: number): unknown {
	if (maxLength <= 0 || value === null || (typeof value !== 'string' && typeof value !== 'object')) {
		return value;
	}
	const text = typeof value === 'string' ? value : JSON.stringify(value);
	return text.length <= maxLength ? value : truncateMiddle(text, maxLength);
}

/** Python's `json.dumps` layout (`", "` and `": "` separators, non-ASCII escaped), as upstream's `to_json`. */
export function pythonJson(value: unknown): string {
	if (value === null || value === undefined) {
		return 'null';
	}
	if (typeof value === 'string') {
		return JSON.stringify(value).replace(
			/[\u007f-￿]/g,
			(char) => `\\u${char.charCodeAt(0).toString(16).padStart(4, '0')}`,
		);
	}
	if (typeof value === 'number' || typeof value === 'boolean') {
		return JSON.stringify(value);
	}
	if (Array.isArray(value)) {
		return `[${value.map(pythonJson).join(', ')}]`;
	}
	if (typeof value === 'object') {
		return `{${Object.entries(value as Record<string, unknown>)
			.map(([key, item]) => `${pythonJson(key)}: ${pythonJson(item)}`)
			.join(', ')}}`;
	}
	return JSON.stringify(String(value));
}
